lations":{},"review":{"fact_id":"49413ff0-3b4f-4154-8d90-0e85b0352621","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"classroom","name":{"en":"In the classroom","zh":"课堂"},"review":{"fact_id":"710e812f-22a9-4d06-a9fb-bf5c7c7bd3d6","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"78b60343-b3aa-440c-af4c-9dc87b9d379b","confidence":0.99,"verdict":"pass"}]}}},{"id":"7808a552-6ef3-4f12-ae37-50a7936b08f7","gloss":"A kind or lovable person, especially one addressed affectionately.","labels":["informal"],"region":"british","rare":false,"translations":{"zh":["亲爱的；讨人喜欢的人"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"f063ac01-a484-4fa0-9510-69cb86a72a04","confidence":0.91,"verdict":"pass"}},"examples":[{"text":"Be a pet and bring me my glasses, would you?","translations":{"zh":"乖，帮我把眼镜拿来，好吗？"},"review":{"fact_id":"61953c16-99f7-4a01-9022-694a048fd7f5","confidence":0.97,"verdict":"pass"}},{"text":"You look tired, pet. Come and sit down.","translations":{"zh":"你看起来累了，亲爱的。过来坐下吧。"},"review":{"fact_id":"7f3034a5-8f5a-43c3-8d5f-2d6476b58586","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"be a pet","pattern":"phrase","translations":{},"review":{"fact_id":"6dbbe48b-5898-4db1-88a3-b50273b6fe9b","confidence":0.94,"verdict":"pass"}}],"topics":[{"id":"communication-styles","name":{"en":"Ways of communicating","zh":"沟通方式"},"review":{"fact_id":"94b52c76-cb0d-4a4e-954b-48e5971a77ae","confidence":0.88,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"8be3370e-d814-42db-84bf-502cc55938ac","confidence":0.98,"verdict":"pass"}]}}}],"review":{"forms":{"plural":[{"fact_id":"3e6dbc55-0c15-41ff-ab33-6204ddb9c7e5","confidence":0.99,"verdict":"pass"}]}}},{"pos":"verb","cefr":null,"pronunciations":[],"forms":{"third_person_singular":[{"form":"pets","irregular":false}],"past":[{"form":"petted","irregular":false}],"past_participle":[{"form":"petted","irregular":false}],"present_participle":[{"form":"petting","irregular":false}]},"senses":[{"id":"fa1061e4-43ba-4d95-a56a-b6a5ae7795fd","gloss":"To stroke or touch an animal gently and affectionately.","labels":[],"region":null,"rare":false,"translations":{"zh":["（亲昵地）抚摸"]},"grammar":{"transitivity":"transitive","patterns":[],"prepositions":[],"review":{"fact_id":"f5787b2d-eed8-412e-95ff-289dc6db9ab6","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"She knelt down to pet the dog.","translations":{"zh":"她跪下来抚摸那只狗。"},"review":{"fact_id":"3f63eecf-8908-43fc-8c45-10d7c39eafb1","confidence":0.99,"verdict":"pass"}},{"text":"Always ask the owner before you pet a strange dog.","translations":{"zh":"抚摸不熟悉的狗之前，一定要先征得主人的同意。"},"review":{"fact_id":"f15e949f-3c77-4da4-9861-77a72015288e","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"pet a dog","pattern":"verb_noun","translations":{},"review":{"fact_id":"8b5290f7-08d3-4694-8867-3a540a48f40b","confidence":0.94,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"review":{"fact_id":"76bf64d5-c6d5-4437-ba47-b2d4230152b3","confidence":0.99,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"74e7d112-7603-478a-8824-c4855361c9af","confidence":0.99,"verdict":"pass"}]}}},{"id":"b5daf037-b6a5-4c4d-b220-620dde3fd4eb","gloss":"To kiss and caress someone in a sexual way.","labels":["dated"],"region":null,"rare":false,"translations":{"zh":["（带有性意味地）亲吻爱抚"]},"grammar":{"transitivity":"intransitive","patterns":[],"prepositions":[],"review":{"fact_id":"25fa6c0a-02fd-4d0c-9915-dc8e4453bee1","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"The couple were petting in the back seat of the car.","translations":{"zh":"那对情侣正在汽车后座上亲吻爱抚。"},"review":{"fact_id":"a07fa307-f913-495b-9bff-b37d11986d08","confidence":0.98,"verdict":"pass"}},{"text":"They spent the evening kissing and petting on the sofa.","translations":{"zh":"他们整晚都在沙发上亲吻爱抚。"},"review":{"fact_id":"0bcba1d1-d76f-47d6-a399-d80376144f02","confidence":0.97,"verdict":"pass"}}],"collocations":[],"topics":[{"id":"relationships","name":{"en":"Relationships and marriage","zh":"恋爱婚姻"},"review":{"fact_id":"5626cc4e-4543-4153-a4bc-ded30e92d5c2","confidence":0.96,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"87fad471-880e-40c2-9c42-15cd5e0e90e3","confidence":0.99,"verdict":"pass"}]}}}],"review":{"forms":{"third_person_singular":[{"fact_id":"20332875-28cd-4299-bf85-97ce96702e88","confidence":0.95,"verdict":"pass"}],"past":[{"fact_id":"e281cab6-3ef7-46ff-9aec-972e439e250d","confidence":0.98,"verdict":"pass"}],"past_participle":[{"fact_id":"82caec5d-0c69-4fad-a070-f51c800bbdfb","confidence":0.98,"verdict":"pass"}],"present_participle":[{"fact_id":"4d43ef39-3794-4b3d-8d97-d826bd7aa5be","confidence":0.96,"verdict":"pass"}]}}},{"pos":"adjective","cefr":null,"pronunciations":[],"forms":{},"senses":[{"id":"a3c1703b-ca42-47b5-b072-7995814d2d4b","gloss":"Kept as a companion animal.","labels":[],"region":null,"rare":false,"translations":{"zh":["作为宠物饲养的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"41e9d2c5-7cec-4a80-8849-fe636f9ce9e4","confidence":0.86,"verdict":"pass"}},"examples":[{"text":"Their pet cat sleeps on the sofa.","translations":{"zh":"他们的宠物猫睡在沙发上。"},"review":{"fact_id":"d1806d69-b5d6-4f02-bf61-9ad73b930995","confidence":0.99,"verdict":"pass"}},{"text":"Our pet rabbit loves fresh carrots.","translations":{"zh":"我们的宠物兔很爱吃新鲜胡萝卜。"},"review":{"fact_id":"244eb5c4-6431-4db8-8225-cee634ffbe16","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"pet dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"4e6aeaa7-62db-4a84-bc7b-674e6b8a2b14","confidence":0.97,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"review":{"fact_id":"831a466e-8cee-4d49-b3df-a7c0d3202684","confidence":1,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"2991fb4b-ff35-4d38-a13d-3cd053a12657","confidence":0.99,"verdict":"pass"}]}}},{"id":"500dfbb8-5f86-46c1-a33f-f595c07ef0df","gloss":"Receiving special personal interest, attention, or affection.","labels":[],"region":null,"rare":false,"translations":{"zh":["特别喜爱的；格外关注的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"13a039bd-e48a-44f2-897d-3c8f91f1eaa4","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"Restoring the old theatre has become her pet project.","translations":{"zh":"修复那座老剧院已成为她格外投入心力的项目。"},"review":{"fact_id":"f11f97e5-5d4b-4132-a938-a61b58404a49","confidence":0.99,"verdict":"pass"}},{"text":"He has a pet theory about why the team keeps losing.","translations":{"zh":"对于这支球队为何总是输球，他有一套自己特别认同的理论。"},"review":{"fact_id":"ad0a7b95-06d9-45ea-a963-8c67382c7e4a","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"pet project","pattern":"adjective_noun","translations":{},"review":{"fact_id":"b4f5fe92-cbf7-48bb-a92b-77a594cc7a43","confidence":0.99,"verdict":"pass"}},{"text":"pet theory","pattern":"adjective_noun","translations":{},"review":{"fact_id":"39521ee8-75c6-422b-9c67-1fe0f742b457","confidence":0.99,"verdict":"pass"}},{"text":"pet hate","pattern":"adjective_noun","translations":{},"review":{"fact_id":"90c626ca-c562-434c-8b73-71468dab5796","confidence":0.97,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"1afa7cd8-e710-49a1-9cdd-f89a80715965","confidence":0.99,"verdict":"pass"}]}}},{"id":"425205d9-920a-43b7-ab7e-910e7f7f63d4","gloss":"Particularly disliked or found annoying.","labels":[],"region":null,"rare":false,"translations":{"zh":["特别讨厌的；格外令人恼火的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"aeb9c848-e5ee-436b-941d-99fa4a37542b","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"People talking loudly on their phones are one of my pet hates.","translations":{"zh":"我最讨厌的事情之一就是有人大声打电话。"},"review":{"fact_id":"05ddda04-ae10-436e-b57b-3b5e2a1c58c5","confidence":0.98,"verdict":"pass"}},{"text":"One of her pet peeves is people leaving dirty dishes in the sink.","translations":{"zh":"她特别反感的一件事是有人把脏餐具留在水槽里。"},"review":{"fact_id":"e5486fa2-0281-40bd-be81-a792ae39f553","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"pet hate","pattern":"adjective_noun","translations":{},"review":{"fact_id":"ef458f1b-22d0-4155-8e6f-bafc03d91b61","confidence":0.98,"verdict":"pass"}},{"text":"pet peeve","pattern":"adjective_noun","translations":{},"review":{"fact_id":"2fcc066a-5eff-4e8a-95fa-bc3092e89232","confidence":0.97,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d439fb0b-1d3a-43f1-97b3-9b803f813053","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"78ae7297-e83e-4806-8df0-9717003a48bb","confidence":0.99,"verdict":"pass"}]}}}],"review":{"f