INSERT OR IGNORE INTO public_entries ("entry_id", "lemma", "document", "digest", "summary", "frequency_order", "built_at") VALUES ('9b4ed2f6-0aa9-4343-9b45-7f37741f78dd', 'dog', '{"id":"9b4ed2f6-0aa9-4343-9b45-7f37741f78dd","lemma":"dog","frequency":{"zipf":5.1,"rank":811},"pronunciations":[{"ipa":"dɒɡ","accent":"uk","review":{"fact_id":"8d8735a6-5ebf-4630-8fa1-8f006aac853f","confidence":0.99,"verdict":"pass"}},{"ipa":"dɔɡ","accent":"us","review":{"fact_id":"3b0fd46a-c756-438d-8cce-a18326991272","confidence":0.98,"verdict":"pass"}}],"variants":[],"syllables":["dog"],"morphology":{"parts":[{"form":"dog","role":"base"}],"review":{"fact_id":"76c44074-bc42-4c7e-8ef9-62f51e6bacd4","confidence":0.96,"verdict":"pass"}},"meanings":[{"pos":"noun","cefr":"A1","pronunciations":[],"forms":{"plural":[{"form":"dogs","irregular":false}]},"senses":[{"id":"dffccb4e-a0b2-4d16-95ae-2489246ff947","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","labels":[],"region":null,"rare":false,"translations":{"zh":["狗"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"f09c1880-3626-4217-8410-6bfc2dd0233d","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"The dog wagged its tail when it saw us.","translations":{"zh":"那只狗看到我们时摇起了尾巴。"},"review":{"fact_id":"9692d743-2e45-4c3a-a42f-aea62a1b1e6a","confidence":0.99,"verdict":"pass"}},{"text":"We take our dog for a walk every morning.","translations":{"zh":"我们每天早上都带狗出去散步。"},"review":{"fact_id":"e19af9b4-6156-46ac-8878-cd16823f7561","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"walk the dog","pattern":"verb_noun","translations":{},"review":{"fact_id":"cae1075e-a842-4219-8bc6-e75cb4b7b574","confidence":0.99,"verdict":"pass"}},{"text":"stray dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"1035d5c2-fefc-4657-81ee-3d772806aa20","confidence":0.99,"verdict":"pass"}},{"text":"guide dog","pattern":"noun_noun","translations":{},"review":{"fact_id":"c2f2ad80-56a3-4119-92b1-f66843d4302f","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"review":{"fact_id":"3cdd024c-d2d3-492b-8501-240c9ce34c50","confidence":1,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"pet","sense_id":"2014af70-ee42-4478-8785-61fccba82f79","gloss":"An animal kept for companionship or pleasure.","review":{"fact_id":"7dc346c5-eabf-458e-8930-03d1cef8965c","confidence":1,"verdict":"pass"}},{"lemma":"animal","sense_id":"f816f9b8-4a89-4b2a-9cb2-424ff9c72a3f","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","review":{"fact_id":"09dfbcab-e0fe-4a70-8ac2-323219524d24","confidence":1,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"d86f04ee-d470-488b-944f-46106c7e3174","confidence":1,"verdict":"pass"}]}}},{"id":"29ebf1fb-d287-44f5-9481-a7cc2a3d451f","gloss":"A male dog or a male of a related animal such as a fox.","labels":[],"region":null,"rare":false,"translations":{"zh":["公狗；雄性犬科动物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"4554deb9-9824-422c-b273-394800a976a8","confidence":0.95,"verdict":"pass"}},"examples":[{"text":"Is your new puppy a dog or a bitch?","translations":{"zh":"你新养的小狗是公的还是母的？"},"review":{"fact_id":"51d21a62-8026-4ea8-927b-660dcfb21d87","confidence":0.99,"verdict":"pass"}},{"text":"The breeder keeps the dogs and bitches in separate kennels.","translations":{"zh":"繁育者把公狗和母狗养在不同的犬舍里。"},"review":{"fact_id":"1ac7c481-0bb2-4724-97d5-68d2a16c4438","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"stud dog","pattern":"noun_noun","translations":{},"review":{"fact_id":"623377ee-501d-4eec-bde2-decfdc11775c","confidence":0.97,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9c28cb5c-9e27-41cc-b701-e86c074270e7","confidence":0.99,"verdict":"pass"}]}}},{"id":"019f3880-da23-4b2e-bdd6-035326f6885d","gloss":"A man described in a familiar or affectionate way as having a particular quality.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["家伙（对男子的亲昵称呼）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"17230db7-44ff-485b-ab0d-3a665d266d72","confidence":0.9,"verdict":"pass"}},"examples":[{"text":"You lucky dog! I wish I could go on holiday too.","translations":{"zh":"你这个幸运的家伙！我也希望能去度假。"},"review":{"fact_id":"3a881793-8b60-44be-9eed-6cdd8c9ce7c2","confidence":0.99,"verdict":"pass"}},{"text":"He''s a sly old dog, but I like him.","translations":{"zh":"他是个狡猾的老家伙，不过我喜欢他。"},"review":{"fact_id":"cebb3f21-e4fd-4623-a646-6faa9f29b5c8","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"lucky dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"ea1a272b-4108-40b6-be6f-9dd22a8dfb49","confidence":0.99,"verdict":"pass"}},{"text":"sly old dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"250b1c0a-108a-44c9-a2ac-7d6058d1ddca","confidence":0.98,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9354213c-7018-46b7-a964-80048f52ac78","confidence":0.99,"verdict":"pass"}]}}},{"id":"18a43355-471e-45de-8c26-5f0e4fc635ea","gloss":"A person, especially a man, regarded as unpleasant or contemptible.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["卑鄙小人；无赖"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"1f7627f8-c883-4750-9792-c854bc2a5928","confidence":0.93,"verdict":"pass"}},"examples":[{"text":"You dirty dog! You knew she was married.","translations":{"zh":"你这个卑鄙的家伙！你明明知道她已经结婚了。"},"review":{"fact_id":"7685c9b9-dd02-4bec-b229-c0069fe45866","confidence":0.99,"verdict":"pass"}},{"text":"That lying dog stole money from his own mother.","translations":{"zh":"那个满嘴谎话的无赖竟然偷自己母亲的钱。"},"review":{"fact_id":"51380731-f5e9-4fcb-9739-807b3898599b","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"dirty dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"362ed66d-4e78-42a2-a187-13a3eff8192b","confidence":0.98,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"962b4530-f259-4893-8ab7-7c42b8b2cfb1","confidence":0.99,"verdict":"pass"}]}}},{"id":"8242b453-1470-4de0-822b-ec49a97a212a","gloss":"Something of very poor quality or something that is a commercial failure.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["劣质品；失败之作"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"3080cf8b-bd9b-4cd2-bdcb-56d5b8563655","confidence":0.88,"verdict":"pass"}},"examples":[{"text":"The used car I bought turned out to be a dog.","translations":{"zh":"我买的那辆二手车结果是辆破车。"},"review":{"fact_id":"4bf9fb1c-870a-4f7b-8d48-aea90f198bbe","confidence":0.99,"verdict":"pass"}},{"text":"Their latest film was a real dog and lost millions at the box office.","translations":{"zh":"他们的最新电影是一部十足的烂片，票房亏损了数百万。"},"review":{"fact_id":"f30822aa-e00a-4caa-b39a-19cb2826e9f5","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"a real dog","pattern":"adjective_noun","translations":{},"review":{"fact_id":"e74c0a61-5764-41da-a232-1c20d5b32c46","confidence":0.92,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"83fc950e-6a6b-4492-b1b9-9e62e1f89a31","confidence":0.99,"verdict":"pass"}]}}},{"id":"7984c21b-e4b3-41f9-b200-2e40c166b569","gloss":"A woman considered physically unattractive.","labels":["offensive"],"region":null,"rare":false,"translations":{"zh":["丑女（侮辱性称呼）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"cf08dab5-f4e3-4f8d-b1ce-38a87e8669b0","confidence":0.89,"verdict":"pass"}},"examples":[{"text":"Calling a woman a dog because you dislike her appearance is insulting.","translations":{"zh":"因为不喜欢一个女人的外貌就叫她“丑女”，是对她的侮辱。"},"review":{"fact_id":"5fb7b247-e681-47eb-8680-49e57f891081","confidence":0.96,"verdict":"pass"}},{"text":"He cruelly called her a dog because of her looks.","translations":{"zh":"他因为她的长相而刻薄地骂她是丑女。"},"review":{"fact_id":"81da25e0-d2bd-4729-8298-da4123bf27af","confidence":0.96,"verdict":"pass"}}],"collocations":[],"topics":[{"id":"appearance","name":{"en":"Appearance","zh":"外貌"},"review":{"fact_id":"11e1855b-7a13-42f7-b535-11e6497e98c6","confidence":0.96,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"402aa1bb-fc44-4966-ad45-326add21708b","confidence":0.99,"verdict":"pass"}]}}},{"id":"d5f2f7ee-1237-4864-a9a6-fd33e4f3e725","gloss":"Greyhound racing, especially as an activity involving betting.","labels":["informal"],"region":"british","rare":false,"translations":{"zh":["赛狗（尤指下注的赛狗活动）"]},"grammar":{"number":"plural_only","article":"with_the","patterns":[],"prepositions":[],"review":{"fact_id":"4ae99572-19eb-4e99-8fc8-951c984348cf","confidence":0.97,"verdict":"pass"}},"examples":[{"text":"We spent an evening at the dogs and placed a few bets.","translations":{"zh":"我们在赛狗场玩了一个晚上，还下了几次注。"},"review":{"fact_id":"d9a44a5c-87f0-4b8b-8a6f-c8e2ee456c0f","confidence":0.99,"verdict":"pass"}},{"text":"My uncle used to go to the dogs every Friday night.","translations":{"zh":"我叔叔以前每周五晚上都去看赛狗。"},"review":{"fact_id":"9a3e293d-43ad-478b-85b6-85e8e2f13aae","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"a night at the dogs","pattern":"phrase","translations":{},"review":{"fact_id":"ef0caffa-12c9-4977-ab09-2bf98f0a1a47","confidence":0.96,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"b28bf015-d86b-4908-88e1-c034597df8b7","confidence":0.99,"verdict":"pass"}]}}},{"id":"1ca80275-50d1-4ff0-b70c-0aad1530e2ce","gloss":"A hot dog.","labels":["informal"],"region":"american","rare":false,"translations":{"zh":["热狗"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"89884084-1839-49f3-b935-c2cb7f75ed49","confidence":0.94,"verdict":"pass"}},"examples":[{"text":"I''ll have a dog with mustard and a large soda.","translations":{"zh":"我要一个加芥末酱的热狗和一大杯汽水。"},"review":{"fact_id":"e7ee86ed-1f9d-4250-ae32-76d6dba0ca3f","confidence":0.99,"verdict":"pass"}},{"text":"We bought a couple of dogs at the baseball game.","translations":{"zh":"我们在棒球比赛现场买了两个热狗。"},"review":{"fact_id":"0d6635c4-a104-49a0-96c2-7b5852727c5f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"chili dog","pattern":"noun_noun","translations":{},"review":{"fact_id":"57e66553-b69b-4dc1-8488-3b24c7de6238","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"restaurant-ordering","name":{"en":"At a restaurant","zh":"餐厅点餐"},"review":{"fact_id":"3e2680b8-6c11-416b-acb6-5fce091f68a5","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"77183119-41c8-4f29-b478-b74570d11467","confidence":1,"verdict":"pass"}]}}},{"id":"86873f91-9809-47ec-a84c-f75652c56c07","gloss":"A person''s feet.","labels":["slang"],"region":"american","rare":false,"translations":{"zh":["双脚"]},"grammar":{"number":"plural_only","patterns":[],"prepositions":[],"review":{"fact_id":"0b627003-e40b-4f98-9daf-c7cd413ed56f","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"After walking all day, my dogs are barking.","translations":{"zh":"走了一整天，我的双脚疼得厉害。"},"review":{"fact_id":"dcac1cb5-a743-4300-b96f-51927eb7f10a","confidence":0.99,"verdict":"pass"}},{"text":"Let me sit down and rest these tired dogs.","translations":{"zh":"让我坐下来，让这双疲惫的脚歇一歇。"},"review":{"fact_id":"49c95989-76be-4dd9-b4c7-a363ec2c63df","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"my dogs are barking","pattern":"phrase","translations":{},"review":{"fact_id":"3d6f4afb-6e0f-47df-a2b2-20ba6d5ad8e1","confidence":0.99,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"51997260-4d99-4931-aa4e-702a07a64217","confidence":0.99,"verdict":"pass"}]}}}],"review":{"forms":{"plural":[{"fact_id":"0f9dc626-f974-43d4-acf8-cb10a783079d","confidence":0.99,"verdict":"pass"}]}}},{"pos":"verb","cefr":null,"pronunciations":[],"forms":{"third_person_singular":[{"form":"dogs","irregular":false}],"past":[{"form":"dogged","irregular":false}],"past_participle":[{"form":"dogged","irregular":false}],"present_participle":[{"form":"dogging","irregular":false}]},"senses":[{"id":"574e33dc-c722-4309-aba8-b40d8fa6bd92","gloss":"To cause persistent trouble or difficulty for someone or something.","labels":[],"region":null,"rare":false,"translations":{"zh":["长期困扰；纠缠"]},"grammar":{"transitivity":"transitive","patterns":[],"prepositions":[],"review":{"fact_id":"0ce2db31-aecc-4629-90d2-140308087583","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"Financial problems have dogged the project from the start.","translations":{"zh":"这个项目从一开始就一直受到资金问题的困扰。"},"review":{"fact_id":"1815580e-5d73-447f-a383-5a729dc5c101","confidence":0.99,"verdict":"pass"}},{"text":"Injuries have dogged him throughout his career.","translations":{"zh":"伤病在他的整个职业生涯中一直困扰着他。"},"review":{"fact_id":"ca62bf2b-0c33-4904-841c-cb88cd0284b6","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"dog someone''s career","pattern":"verb_noun","translations":{},"review":{"fact_id":"c98afb9c-e616-4a0d-9b3a-0e2ffe49b677","confidence":0.95,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"6e278390-dc97-46ea-90cb-6e0d65d60ce9","confidence":0.98,"verdict":"pass"}]}}},{"id":"6f76b01f-a4be-4fb2-87fc-2cf08824f14e","gloss":"To follow someone closely and persistently.","labels":[],"region":null,"rare":false,"translations":{"zh":["紧随；尾随"]},"grammar":{"transitivity":"transitive","patterns":[],"prepositions":[],"review":{"fact_id":"1eace05f-5a86-4779-8fa8-1b0bd4fd03ff","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"Photographers dogged the actor wherever he went.","translations":{"zh":"这位演员走到哪里，摄影记者就紧跟到哪里。"},"review":{"fact_id":"ea6e475f-f0e4-40dd-88ba-5c08295f8fb9","confidence":0.99,"verdict":"pass"}},{"text":"Reporters dogged her every step as she left the courthouse.","translations":{"zh":"她离开法院时，记者们步步紧跟着她。"},"review":{"fact_id":"c2a11f01-4452-4856-9aac-4151a495015e","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"dog someone''s footsteps","pattern":"verb_noun","translations":{},"review":{"fact_id":"210342fe-f311-49b5-a0af-ad8ff608a52c","confidence":0.95,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"translations":{"zh":[{"fact_id":"67525563-9d2e-4154-9e21-4eaecd94c058","confidence":0.99,"verdict":"pass"}]}}}],"review":{"forms":{"third_person_singular":[{"fact_id":"913a8293-ae58-474f-92d7-f27160846f72","confidence":0.95,"verdict":"pass"}],"past":[{"fact_id":"9c4e08c4-35fd-4c9d-b3b2-f9276b4d2f76","confidence":0.93,"verdict":"pass"}],"past_participle":[{"fact_id":"63f253e3-ec71-4168-8937-ec0436fe9d62","confidence":0.95,"verdict":"pass"}],"present_participle":[{"fact_id":"d08f669f-40f2-4d2c-a4ad-d34a00c2e40f","confidence":0.96,"verdict":"pass"}]}}}],"summary":{"lemma":"dog","pos":["noun","verb"],"cefr":"A1","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","translations":{"zh":"狗"}},"phrases":[],"review":{"inventory":{"fact_id":"78a7f24b-4ed0-4bd5-ad77-f600030bd5f0","confidence":0.88,"verdict":"pass"},"syllables":{"fact_id":"53fb2c26-af07-4f3d-8e9b-957906a9581a","confidence":1,"verdict":"pass"},"phrases":null},"forms":[{"form":"dogs","type":"plural","pos":"noun"},{"form":"dogs","type":"third_person_singular","pos":"verb"},{"form":"dogged","type":"past","pos":"verb"},{"form":"dogged","type":"past_participle","pos":"verb"},{"form":"dogging","type":"present_participle","pos":"verb"}]}', 'd529a755a8b96a1a70191580706c7819', '{"lemma":"dog","pos":["noun","verb"],"cefr":"A1","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","translations":{"zh":"狗"}}', 811, '2026-11-12T05:05:30.765Z');
