INSERT OR IGNORE INTO public_entries ("entry_id", "lemma", "document", "digest", "summary", "frequency_order", "built_at") VALUES ('bb313d03-e221-465f-9bac-54677b966447', 'animal', '{"id":"bb313d03-e221-465f-9bac-54677b966447","lemma":"animal","frequency":{"zipf":4.81,"rank":1611},"pronunciations":[{"ipa":"ˈænɪməl","accent":"us","review":{"fact_id":"6758af98-1c07-4a16-a7d7-9d234e64fb00","confidence":0.98,"verdict":"pass"}},{"ipa":"ˈænɪməl","accent":"uk","review":{"fact_id":"76da71b8-c95c-47f1-ab32-02a741abf0a8","confidence":0.99,"verdict":"pass"}}],"variants":[],"syllables":["an","i","mal"],"morphology":{"parts":[{"form":"animal","role":"base"}],"review":{"fact_id":"83e70b3e-6ac6-4f77-972a-b135d3852c54","confidence":0.92,"verdict":"pass"}},"meanings":[{"pos":"noun","cefr":"A1","pronunciations":[],"forms":{"plural":[{"form":"animals","irregular":false}]},"senses":[{"id":"f816f9b8-4a89-4b2a-9cb2-424ff9c72a3f","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"4f500b21-15be-4ae4-bbdd-6db89ab0dd89","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"Please do not feed the animals at the zoo.","translations":{"zh":"请不要给动物园里的动物喂食。"},"review":{"fact_id":"65001cec-c599-4fc3-8b15-8a455de73946","confidence":1,"verdict":"pass"}},{"text":"The farm keeps animals such as cows, pigs, and sheep.","translations":{"zh":"这家农场饲养牛、猪、羊等动物。"},"review":{"fact_id":"5dc3420c-aa4b-459d-91da-a71a6419712f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"wild animal","pattern":"adjective_noun","translations":{},"review":{"fact_id":"8c49a817-a0e3-434e-8100-0dfa60ab86ca","confidence":0.99,"verdict":"pass"}},{"text":"domestic animal","pattern":"adjective_noun","translations":{},"review":{"fact_id":"8c4e9746-351c-486e-9163-8c3d68bc9a56","confidence":0.99,"verdict":"pass"}},{"text":"farm animal","pattern":"noun_noun","translations":{},"review":{"fact_id":"46a688fc-1cb0-4bc9-9110-6ac90088cfac","confidence":0.98,"verdict":"pass"}}],"topics":[{"id":"wild-animals","name":{"en":"Wild animals","zh":"野生动物"},"review":{"fact_id":"1c1923ba-b5bb-4c49-b679-bad80dae3f8b","confidence":0.98,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"creature","sense_id":"b27a4c22-8ffb-4be7-8f4f-3dc845cd49b3","gloss":"A living being, especially an animal.","review":{"fact_id":"c57b6c9a-2298-4414-8ebb-0435e5157daf","confidence":1,"verdict":"pass"}}],"narrower":[{"lemma":"bird","sense_id":"03bfbc15-e191-42e0-a2d7-de49f4207316","gloss":"An animal with feathers, wings, and a beak that lays eggs and is usually able to fly.","review":{"fact_id":"6b1377a1-7482-4cd1-a8fc-20fd1a577794","confidence":1,"verdict":"pass"}},{"lemma":"fish","sense_id":"e06e6007-6ca9-4e57-8416-f0c18438eba7","gloss":"An animal that lives in water, breathes through gills, and has fins.","review":{"fact_id":"4ed0c5c6-f2ba-487b-b162-fae3f468d67a","confidence":1,"verdict":"pass"}},{"lemma":"pet","sense_id":"2014af70-ee42-4478-8785-61fccba82f79","gloss":"An animal kept for companionship or pleasure.","review":{"fact_id":"2e4c027e-1615-4790-a065-11b6cbae5e04","confidence":1,"verdict":"pass"}},{"lemma":"dog","sense_id":"dffccb4e-a0b2-4d16-95ae-2489246ff947","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","review":{"fact_id":"09dfbcab-e0fe-4a70-8ac2-323219524d24","confidence":1,"verdict":"pass"}},{"lemma":"cat","sense_id":"af217c59-c334-4cec-b4a4-2bcf923341d4","gloss":"A small domesticated animal with soft fur, whiskers, and retractable claws, often kept as a pet.","review":{"fact_id":"ba9ac27e-527e-4131-b3c2-4bb75b0a540e","confidence":1,"verdict":"pass"}},{"lemma":"cat","sense_id":"eef6d786-77bb-47fa-8c96-8a2c82c112b3","gloss":"A wild animal of the same family as the domestic cat, including lions, tigers, and leopards.","review":{"fact_id":"24d2ceba-ecb5-478f-bb5d-a99547bba224","confidence":1,"verdict":"pass"}}],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9d33d3e5-896d-4534-afc1-7add68710ab3","confidence":1,"verdict":"pass"}]}}},{"id":"cbcbbe15-4e8b-4732-8707-49ace61b3c23","gloss":"Any living creature, including a human, as opposed to a plant.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物（包括人类）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"dc79062c-8ed9-4eb1-b204-c01e1482c958","confidence":0.88,"verdict":"pass"}},"examples":[{"text":"Unlike plants, animals cannot make their own food using sunlight.","translations":{"zh":"与植物不同，动物不能利用阳光自行制造食物。"},"review":{"fact_id":"1d535ad0-f3da-4352-9bd0-576f565451c2","confidence":0.99,"verdict":"pass"}},{"text":"Humans, jellyfish, and ants are all animals.","translations":{"zh":"人类、水母和蚂蚁都是动物。"},"review":{"fact_id":"9c563942-98cc-412c-8472-e65b6334d636","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"social animal","pattern":"adjective_noun","translations":{},"review":{"fact_id":"daa9ccae-40e9-426d-aa05-464f20937cff","confidence":0.96,"verdict":"pass"}},{"text":"marine animal","pattern":"adjective_noun","translations":{},"review":{"fact_id":"da7141a9-135a-420c-963a-6271b40d9844","confidence":0.91,"verdict":"pass"}}],"topics":[{"id":"biology","name":{"en":"Biology","zh":"生物"},"review":{"fact_id":"d9e3b1ba-bfd0-43b5-a3f8-3354ac24191c","confidence":0.99,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"c50b0dfe-56f9-416b-9529-712ea22ff0d2","confidence":1,"verdict":"pass"}]}}},{"id":"715cf83d-8d69-4f47-9251-5b81317e69f7","gloss":"A person who behaves in a cruel, violent, or uncivilized way.","labels":[],"region":null,"rare":false,"translations":{"zh":["畜生；野蛮残暴的人"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"cc8fd09c-71bf-4e6e-9dbd-fcf02723c250","confidence":0.93,"verdict":"pass"}},"examples":[{"text":"The prisoners described the guard who tortured them as an animal.","translations":{"zh":"囚犯们称那个折磨他们的看守是个畜生。"},"review":{"fact_id":"219b00e7-2364-4525-939d-c0ff05df2d2f","confidence":0.99,"verdict":"pass"}},{"text":"Anyone who could beat a defenseless child like that is an animal.","translations":{"zh":"能那样殴打一个毫无还手之力的孩子的人，简直是个畜生。"},"review":{"fact_id":"d6625354-f71f-4ba9-8d2a-858bc04dd928","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"behave like an animal","pattern":"phrase","translations":{},"review":{"fact_id":"d2275c22-69a3-4334-9dcd-942fd462a871","confidence":0.91,"verdict":"pass"}}],"topics":[{"id":"personality","name":{"en":"Personality","zh":"性格"},"review":{"fact_id":"0f0b3f56-ae3a-4e53-915f-e6f150a4f1ae","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"eab49ec3-3442-4477-8b97-646df7bd0380","confidence":0.99,"verdict":"pass"}]}}},{"id":"9f7d682a-d218-4bd4-961c-9689d44c22b3","gloss":"A person or thing of a particular type.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["某一类型的人或事物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"7d1a4c0d-f811-410c-a381-2f746c7a62bd","confidence":0.92,"verdict":"pass"}},"examples":[{"text":"Running a large company is a very different animal from managing a small shop.","translations":{"zh":"经营一家大公司与管理一家小店完全是两码事。"},"review":{"fact_id":"7aceea50-81be-47d9-aa42-2ffe1d9cd642","confidence":0.99,"verdict":"pass"}},{"text":"She is a political animal who loves campaigning and debating.","translations":{"zh":"她是个热衷政治的人，喜欢参加竞选活动和辩论。"},"review":{"fact_id":"d3a08b6e-fe92-4135-b110-033d9a905ff2","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"a different animal","pattern":"phrase","translations":{},"review":{"fact_id":"4166c340-2037-494d-bc2c-8daa57484e18","confidence":0.97,"verdict":"pass"}},{"text":"political animal","pattern":"adjective_noun","translations":{},"review":{"fact_id":"c30afd5a-d584-4707-83d7-92d6330c82a6","confidence":0.99,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"3c47b9eb-46ca-4291-8a7d-a964f5b035f9","confidence":0.99,"verdict":"pass"}]}}}],"review":{"forms":{"plural":[{"fact_id":"087e1c98-b350-492d-b499-979af9d62415","confidence":0.99,"verdict":"pass"}]}}},{"pos":"adjective","cefr":null,"pronunciations":[],"forms":{},"senses":[{"id":"ee2f1833-230d-4427-a60d-5e693f40e930","gloss":"Relating to animals or derived from animals.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物的；动物来源的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"babc08bd-f0c9-4116-9ed4-ae25e93dd582","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"The soap contains no animal fat.","translations":{"zh":"这种肥皂不含动物脂肪。"},"review":{"fact_id":"1ea01eab-a4ee-44b8-9002-9e1336ae7e69","confidence":0.99,"verdict":"pass"}},{"text":"She avoids eating animal products, including meat, milk, and eggs.","translations":{"zh":"她不吃肉、奶、蛋等动物性食品。"},"review":{"fact_id":"710da19d-7040-447a-ad43-369a8475f1ad","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"animal products","pattern":"adjective_noun","translations":{},"review":{"fact_id":"76f5150b-417b-4efc-8de0-63973cba3138","confidence":0.97,"verdict":"pass"}},{"text":"animal welfare","pattern":"adjective_noun","translations":{},"review":{"fact_id":"ae29a65a-91ba-43ba-83f2-91ccd01345ff","confidence":0.96,"verdict":"pass"}},{"text":"animal fat","pattern":"adjective_noun","translations":{},"review":{"fact_id":"08c5c447-2361-44af-8112-e11e45f51863","confidence":0.98,"verdict":"pass"}}],"topics":[{"id":"biology","name":{"en":"Biology","zh":"生物"},"review":{"fact_id":"02792d78-f81b-4088-86fb-0ed52b029240","confidence":0.98,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"ee679596-054f-488b-a65f-fbb3f506a222","confidence":0.99,"verdict":"pass"}]}}},{"id":"bdf88512-73ef-42f4-8639-bffa1020f37d","gloss":"Relating to physical appetites and instincts rather than reason or spiritual qualities.","labels":[],"region":null,"rare":false,"translations":{"zh":["肉体欲望的；本能的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"059bf872-69ed-43d4-a564-84777ee0fb55","confidence":0.97,"verdict":"pass"}},"examples":[{"text":"Hunger brought out their most basic animal instincts.","translations":{"zh":"饥饿激发了他们最原始的动物本能。"},"review":{"fact_id":"de2391bb-7849-4abd-a75c-6eb1f86048c2","confidence":0.99,"verdict":"pass"}},{"text":"In his panic, animal instinct took over and he ran for his life.","translations":{"zh":"惊慌之中，本能占了上风，他拼命逃跑。"},"review":{"fact_id":"b8ce65e9-e79d-4f2a-a207-07c51f768a40","confidence":0.95,"verdict":"pass"}}],"collocations":[{"text":"animal instincts","pattern":"adjective_noun","translations":{},"review":{"fact_id":"de33f1e4-3ed0-41d9-b1e5-05c574e3dd58","confidence":0.98,"verdict":"pass"}},{"text":"animal passions","pattern":"adjective_noun","translations":{},"review":{"fact_id":"0caebfb7-df30-4af6-9071-96e57b38b660","confidence":0.96,"verdict":"pass"}},{"text":"animal appetites","pattern":"adjective_noun","translations":{},"review":{"fact_id":"fbddb0b5-6e22-45cd-9f0c-323888408290","confidence":0.96,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"a582a152-2840-491e-a769-52fb83296c3a","confidence":0.95,"verdict":"pass"}]}}}],"review":{"forms":{}}}],"summary":{"lemma":"animal","pos":["noun","adjective"],"cefr":"A1","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","translations":{"zh":"动物"}},"phrases":[],"review":{"inventory":{"fact_id":"ff146a4a-a08b-48fa-b637-6d328c2fa943","confidence":1,"verdict":"pass"},"syllables":{"fact_id":"6b67bd8f-37bb-4a50-a5e5-ec7e00fa38f6","confidence":0.99,"verdict":"pass"},"phrases":null},"forms":[{"form":"animals","type":"plural","pos":"noun"}]}', '5aaec948e262f53ed8d8ffcebbb5814f', '{"lemma":"animal","pos":["noun","adjective"],"cefr":"A1","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","translations":{"zh":"动物"}}', 1611, '2026-11-12T05:05:30.841Z');
